=== FILE: apb_gpio.v ===
`timescale 1ns/1ps
`default_nettype none
// apb_gpio: general-purpose I/O, up to 32 pins, behind an APB4 completer.
// Zero wait states (pready tied high); writes commit on the completing edge.
// Reset is synchronous, active low (presetn), and covers every flop.
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0..N-1 set: pins that exist.
    localparam [31:0] PINS = {32{1'b1}} >> (32 - N);

    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // State
    reg [31:0] data_out_q;
    reg [31:0] dir_q;
    reg [31:0] rise_en_q;
    reg [31:0] fall_en_q;
    reg [31:0] high_en_q;
    reg [31:0] low_en_q;
    reg [31:0] intr_en_q;
    reg [31:0] status_q;
    reg [31:0] in_q;
    reg [31:0] in_prev_q;

    // APB decode
    wire        apb_access = psel & penable;
    wire [3:0]  idx        = paddr[5:2];
    wire        upper_zero = ~|paddr[ADDR_WIDTH-1:6];
    wire        mapped     = (paddr[1:0] == 2'b00) & upper_zero & (idx <= IDX_INTR_STATUS);
    wire        ro_write   = pwrite & (idx == IDX_DATA_IN);
    wire        wr_en      = apb_access & pwrite & mapped & ~ro_write;
    wire        rd_en      = apb_access & ~pwrite & mapped;

    // Write mask: byte strobes expanded, limited to existing pins
    wire [31:0] wmask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;
    wire [31:0] wkeep = ~wmask;
    wire [31:0] wnew  = pwdata & wmask;

    // Input widened to 32 bits, zeros above N
    reg [31:0] gpio_in_w;
    always @* begin
        gpio_in_w        = 32'd0;
        gpio_in_w[N-1:0] = gpio_in;
    end

    // Detection and status
    wire [31:0] rise     = in_q & ~in_prev_q;
    wire [31:0] fall     = ~in_q & in_prev_q;
    wire [31:0] detected = ((rise & rise_en_q) | (fall & fall_en_q)
                          | (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
    wire [31:0] clear    = (wr_en && (idx == IDX_INTR_STATUS)) ? wnew : 32'd0;
    wire [31:0] status_d = (status_q & ~clear) | detected;

    // Read multiplexer
    reg [31:0] rd_mux;
    always @* begin
        case (idx)
            IDX_DATA_OUT:    rd_mux = data_out_q;
            IDX_DIR:         rd_mux = dir_q;
            IDX_DATA_IN:     rd_mux = in_q;
            IDX_INTR_RISE:   rd_mux = rise_en_q;
            IDX_INTR_FALL:   rd_mux = fall_en_q;
            IDX_INTR_HIGH:   rd_mux = high_en_q;
            IDX_INTR_LOW:    rd_mux = low_en_q;
            IDX_INTR_ENABLE: rd_mux = intr_en_q;
            IDX_INTR_STATUS: rd_mux = status_q;
            default:         rd_mux = 32'd0;
        endcase
    end

    // Registers
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            rise_en_q  <= 32'd0;
            fall_en_q  <= 32'd0;
            high_en_q  <= 32'd0;
            low_en_q   <= 32'd0;
            intr_en_q  <= 32'd0;
            status_q   <= 32'd0;
            in_q       <= 32'd0;
            in_prev_q  <= 32'd0;
        end else begin
            in_q      <= gpio_in_w;
            in_prev_q <= in_q;
            status_q  <= status_d;
            if (wr_en) begin
                case (idx)
                    IDX_DATA_OUT:    data_out_q <= (data_out_q & wkeep) | wnew;
                    IDX_DIR:         dir_q      <= (dir_q      & wkeep) | wnew;
                    IDX_INTR_RISE:   rise_en_q  <= (rise_en_q  & wkeep) | wnew;
                    IDX_INTR_FALL:   fall_en_q  <= (fall_en_q  & wkeep) | wnew;
                    IDX_INTR_HIGH:   high_en_q  <= (high_en_q  & wkeep) | wnew;
                    IDX_INTR_LOW:    low_en_q   <= (low_en_q   & wkeep) | wnew;
                    IDX_INTR_ENABLE: intr_en_q  <= (intr_en_q  & wkeep) | wnew;
                    default: ;
                endcase
            end
        end
    end

    // Outputs
    assign prdata   = rd_en ? rd_mux : 32'd0;
    assign pready   = 1'b1;
    assign pslverr  = apb_access & (~mapped | ro_write);
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & intr_en_q);

`ifdef FORMAL
    // Design-intent assertions (not run in this submission).
    always @* begin
        assert (pready == 1'b1);
        if (!apb_access) assert ((prdata == 32'd0) && (pslverr == 1'b0));
        if (pslverr) assert (prdata == 32'd0);
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
`timescale 1ns/1ps
// Self-checking testbench for apb_gpio at N=8 and N=32 (shared bus and pins).
module apb_gpio_tb;

    localparam [31:0] M8 = 32'h000000FF;
    localparam [7:0] A_DATA_OUT = 8'h00;
    localparam [7:0] A_DIR      = 8'h04;
    localparam [7:0] A_DATA_IN  = 8'h08;
    localparam [7:0] A_RISE     = 8'h0C;
    localparam [7:0] A_FALL     = 8'h10;
    localparam [7:0] A_HIGH     = 8'h14;
    localparam [7:0] A_LOW      = 8'h18;
    localparam [7:0] A_EN       = 8'h1C;
    localparam [7:0] A_STATUS   = 8'h20;

    reg         pclk = 1'b0;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] gin;

    wire [31:0] prdata8, prdata32;
    wire        pready8, pready32, pslverr8, pslverr32;
    wire [7:0]  gpio_out8, gpio_oe8;
    wire [31:0] gpio_out32, gpio_oe32;
    wire        irq8, irq32;

    integer passed;
    integer failed;
    reg [31:0] rd8, rd32;
    reg        err8, err32;
    reg [8*64-1:0] nonce;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
        .gpio_in(gin[7:0]), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8), .irq(irq8)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gin), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32), .irq(irq32)
    );

    always #5 pclk = ~pclk;

    task chk(input ok, input [8*64-1:0] msg);
        begin
            if (ok) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check failed: %0s", msg);
            end
        end
    endtask

    // One APB transfer: setup at a falling edge, access at the next,
    // completion on the following rising edge. Bus idles at posedge+1, so a
    // following transfer starts its setup with no idle edge (back to back).
    task apb_xfer(input w, input [7:0] a, input [31:0] d, input [3:0] s);
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = w; paddr = a;
            pwdata = w ? d : 32'h0; pstrb = w ? s : 4'h0;
            #1;
            chk((prdata8 == 32'h0) && (prdata32 == 32'h0), "setup: prdata zero");
            chk((pslverr8 == 1'b0) && (pslverr32 == 1'b0), "setup: pslverr zero");
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk(pready8 && pready32, "access: pready high");
            rd8 = prdata8; rd32 = prdata32; err8 = pslverr8; err32 = pslverr32;
            @(posedge pclk);
            #1;
            psel = 1'b0; penable = 1'b0;
        end
    endtask

    // Write whose setup cycle also drives new pin values.
    task apb_write_pin(input [7:0] a, input [31:0] d, input [3:0] s, input [31:0] pins);
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = 1'b1; paddr = a;
            pwdata = d; pstrb = s; gin = pins;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            err8 = pslverr8; err32 = pslverr32;
            @(posedge pclk);
            #1;
            psel = 1'b0; penable = 1'b0;
            chk((err8 == 1'b0) && (err32 == 1'b0), "write with pin change: no pslverr");
        end
    endtask

    task wr_expect(input [7:0] a, input [31:0] d, input [3:0] s, input experr,
                   input [8*64-1:0] msg);
        begin
            apb_xfer(1'b1, a, d, s);
            chk((err8 == experr) && (err32 == experr), msg);
        end
    endtask

    task rd_expect2(input [7:0] a, input [31:0] e8, input [31:0] e32, input experr,
                    input [8*64-1:0] msg);
        begin
            apb_xfer(1'b0, a, 32'h0, 4'h0);
            chk(rd8 == e8, msg);
            chk(rd32 == e32, msg);
            chk((err8 == experr) && (err32 == experr), msg);
        end
    endtask

    task rd_expect(input [7:0] a, input [31:0] e, input experr, input [8*64-1:0] msg);
        begin
            rd_expect2(a, e & M8, e, experr, msg);
        end
    endtask

    task drive_pins(input [31:0] v);
        begin
            @(negedge pclk);
            gin = v;
        end
    endtask

    task idle(input integer n);
        begin
            repeat (n) @(posedge pclk);
            #1;
        end
    endtask

    task check_all_zero;
        begin
            chk((gpio_out8 == 8'h00) && (gpio_oe8 == 8'h00) && (irq8 == 1'b0), "zero: N=8 outputs");
            chk((gpio_out32 == 32'h0) && (gpio_oe32 == 32'h0) && (irq32 == 1'b0), "zero: N=32 outputs");
            rd_expect(A_DATA_OUT, 32'h0, 1'b0, "zero: DATA_OUT");
            rd_expect(A_DIR,      32'h0, 1'b0, "zero: DIR");
            rd_expect(A_DATA_IN,  32'h0, 1'b0, "zero: DATA_IN");
            rd_expect(A_RISE,     32'h0, 1'b0, "zero: INTR_RISE");
            rd_expect(A_FALL,     32'h0, 1'b0, "zero: INTR_FALL");
            rd_expect(A_HIGH,     32'h0, 1'b0, "zero: INTR_HIGH");
            rd_expect(A_LOW,      32'h0, 1'b0, "zero: INTR_LOW");
            rd_expect(A_EN,       32'h0, 1'b0, "zero: INTR_ENABLE");
            rd_expect(A_STATUS,   32'h0, 1'b0, "zero: INTR_STATUS");
        end
    endtask

    task test_rw(input [7:0] a);
        begin
            wr_expect(a, 32'h00000000, 4'hF, 1'b0, "rw: write zero");
            rd_expect(a, 32'h00000000, 1'b0, "rw: read zero");
            wr_expect(a, 32'hFFFFFFFF, 4'hF, 1'b0, "rw: write ones");
            rd_expect(a, 32'hFFFFFFFF, 1'b0, "rw: ones, bits above N read zero");
            wr_expect(a, 32'h00000000, 4'hF, 1'b0, "rw: write zero again");
            wr_expect(a, 32'hA5A5A5A5, 4'b0101, 1'b0, "rw: strobe 0101");
            rd_expect(a, 32'h00A500A5, 1'b0, "rw: read after strobe 0101");
            wr_expect(a, 32'h5A5A5A5A, 4'b1010, 1'b0, "rw: strobe 1010");
            rd_expect(a, 32'h5AA55AA5, 1'b0, "rw: read after strobe 1010");
            wr_expect(a, 32'hFFFFFFFF, 4'b0000, 1'b0, "rw: no strobes");
            rd_expect(a, 32'h5AA55AA5, 1'b0, "rw: unchanged by no-strobe write");
            wr_expect(a, 32'h12345678, 4'b1000, 1'b0, "rw: strobe 1000");
            rd_expect(a, 32'h12A55AA5, 1'b0, "rw: read after strobe 1000");
        end
    endtask

    initial begin : watchdog
        #2000000;
        failed = failed + 1;
        $error("timeout");
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        passed = 0; failed = 0;
        presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
        paddr = 8'h00; pwdata = 32'h0; pstrb = 4'h0; gin = 32'h0;
        rd8 = 32'h0; rd32 = 32'h0; err8 = 1'b0; err32 = 1'b0;

        // ---- Reset ----
        repeat (4) @(posedge pclk);
        #1;
        chk((gpio_out8 == 8'h00) && (gpio_oe8 == 8'h00) && (irq8 == 1'b0), "in reset: N=8 outputs low");
        chk((gpio_out32 == 32'h0) && (gpio_oe32 == 32'h0) && (irq32 == 1'b0), "in reset: N=32 outputs low");
        @(negedge pclk);
        presetn = 1'b1;
        check_all_zero;

        // ---- Read/write registers, strobes, bits above N ----
        test_rw(A_DATA_OUT);
        chk(gpio_out8 == 8'hA5, "gpio_out N=8 follows DATA_OUT");
        chk(gpio_out32 == 32'h12A55AA5, "gpio_out N=32 follows DATA_OUT");
        test_rw(A_DIR);
        chk(gpio_oe8 == 8'hA5, "gpio_oe N=8 follows DIR");
        chk(gpio_oe32 == 32'h12A55AA5, "gpio_oe N=32 follows DIR");
        test_rw(A_RISE);
        test_rw(A_FALL);
        test_rw(A_HIGH);
        test_rw(A_LOW);
        test_rw(A_EN);
        wr_expect(A_DATA_OUT, 32'h0, 4'hF, 1'b0, "zero DATA_OUT");
        wr_expect(A_DIR,      32'h0, 4'hF, 1'b0, "zero DIR");
        wr_expect(A_RISE,     32'h0, 4'hF, 1'b0, "zero INTR_RISE");
        wr_expect(A_FALL,     32'h0, 4'hF, 1'b0, "zero INTR_FALL");
        wr_expect(A_HIGH,     32'h0, 4'hF, 1'b0, "zero INTR_HIGH");
        wr_expect(A_LOW,      32'h0, 4'hF, 1'b0, "zero INTR_LOW");
        wr_expect(A_EN,       32'h0, 4'hF, 1'b0, "zero INTR_ENABLE");
        wr_expect(A_STATUS,   32'hFFFFFFFF, 4'hF, 1'b0, "clear all status");
        rd_expect(A_STATUS, 32'h0, 1'b0, "status clear after W1C all");
        chk((irq8 == 1'b0) && (irq32 == 1'b0), "irq low after clear");
        chk((gpio_out8 == 8'h00) && (gpio_oe8 == 8'h00), "N=8 pins back to zero");
        chk((gpio_out32 == 32'h0) && (gpio_oe32 == 32'h0), "N=32 pins back to zero");

        // ---- DATA_IN: sampled, read only ----
        drive_pins(32'hDEADBEEF);
        idle(1);
        rd_expect2(A_DATA_IN, 32'h000000EF, 32'hDEADBEEF, 1'b0, "DATA_IN reads sample");
        wr_expect(A_DATA_IN, 32'h0, 4'hF, 1'b1, "DATA_IN write gets PSLVERR");
        rd_expect2(A_DATA_IN, 32'h000000EF, 32'hDEADBEEF, 1'b0, "DATA_IN unchanged by write");
        rd_expect(A_STATUS, 32'h0, 1'b0, "no detection with enables off");
        drive_pins(32'h0);
        idle(2);
        rd_expect(A_DATA_IN, 32'h0, 1'b0, "DATA_IN back to zero");

        // ---- PSLVERR policy and unmapped addresses ----
        wr_expect(A_DATA_OUT, 32'h00000003, 4'hF, 1'b0, "DATA_OUT = 3");
        wr_expect(8'h01, 32'hFFFFFFFF, 4'hF, 1'b1, "unaligned write 0x01 PSLVERR");
        wr_expect(8'h02, 32'hFFFFFFFF, 4'hF, 1'b1, "unaligned write 0x02 PSLVERR");
        wr_expect(8'h24, 32'hFFFFFFFF, 4'hF, 1'b1, "write 0x24 PSLVERR");
        wr_expect(8'h40, 32'hFFFFFFFF, 4'hF, 1'b1, "write alias 0x40 PSLVERR");
        wr_expect(8'h80, 32'hFFFFFFFF, 4'hF, 1'b1, "write alias 0x80 PSLVERR");
        wr_expect(8'hFC, 32'hFFFFFFFF, 4'hF, 1'b1, "write 0xFC PSLVERR");
        rd_expect(A_DATA_OUT, 32'h00000003, 1'b0, "unmapped writes change nothing");
        chk((gpio_out8 == 8'h03) && (gpio_out32 == 32'h3), "gpio_out unchanged by unmapped");
        rd_expect(8'h02, 32'h0, 1'b1, "unaligned read zero, PSLVERR");
        rd_expect(8'h24, 32'h0, 1'b1, "read 0x24 zero, PSLVERR");
        rd_expect(8'h3C, 32'h0, 1'b1, "read 0x3C zero, PSLVERR");
        rd_expect(8'h40, 32'h0, 1'b1, "read alias 0x40 zero, PSLVERR");
        rd_expect(8'h80, 32'h0, 1'b1, "read alias 0x80 zero, PSLVERR");
        wr_expect(A_DATA_OUT, 32'h0, 4'hF, 1'b0, "DATA_OUT = 0");

        // ---- Rising edge: timing, fires once ----
        wr_expect(A_EN,   32'h1, 4'hF, 1'b0, "enable irq bit 0");
        wr_expect(A_RISE, 32'h1, 4'hF, 1'b0, "rise enable bit 0");
        drive_pins(32'h1);
        @(posedge pclk); #1;
        chk((irq8 == 1'b0) && (irq32 == 1'b0), "rise: no status on sample edge");
        @(posedge pclk); #1;
        chk((irq8 == 1'b1) && (irq32 == 1'b1), "rise: status and irq next edge");
        rd_expect(A_STATUS, 32'h1, 1'b0, "rise: status bit 0");
        wr_expect(A_STATUS, 32'h1, 4'h1, 1'b0, "rise: clear bit 0");
        chk((irq8 == 1'b0) && (irq32 == 1'b0), "rise: irq low after clear");
        idle(3);
        rd_expect(A_STATUS, 32'h0, 1'b0, "rise: edge fires once");
        wr_expect(A_EN, 32'h0, 4'hF, 1'b0, "disable irq");

        // ---- Falling edge ----
        drive_pins(32'h3);
        idle(2);
        rd_expect(A_STATUS, 32'h0, 1'b0, "fall: rise on pin1 not enabled");
        wr_expect(A_FALL, 32'h2, 4'hF, 1'b0, "fall enable bit 1");
        drive_pins(32'h1);
        idle(2);
        rd_expect(A_STATUS, 32'h2, 1'b0, "fall: status bit 1");
        wr_expect(A_STATUS, 32'h2, 4'h1, 1'b0, "fall: clear bit 1");
        rd_expect(A_STATUS, 32'h0, 1'b0, "fall: cleared");
        wr_expect(A_FALL, 32'h0, 4'hF, 1'b0, "fall disable");

        // ---- High level: sets again after clear ----
        wr_expect(A_HIGH, 32'h4, 4'hF, 1'b0, "high enable bit 2");
        drive_pins(32'h5);
        idle(2);
        rd_expect(A_STATUS, 32'h4, 1'b0, "high: status bit 2");
        wr_expect(A_STATUS, 32'h4, 4'h1, 1'b0, "high: clear while level holds");
        rd_expect(A_STATUS, 32'h4, 1'b0, "high: level sets again");
        drive_pins(32'h1);
        idle(2);
        wr_expect(A_STATUS, 32'h4, 4'h1, 1'b0, "high: clear after level gone");
        rd_expect(A_STATUS, 32'h0, 1'b0, "high: cleared");
        wr_expect(A_HIGH, 32'h0, 4'hF, 1'b0, "high disable");

        // ---- Low level: sets again after clear ----
        wr_expect(A_LOW, 32'h8, 4'hF, 1'b0, "low enable bit 3");
        rd_expect(A_STATUS, 32'h8, 1'b0, "low: status bit 3");
        wr_expect(A_STATUS, 32'h8, 4'h1, 1'b0, "low: clear while level holds");
        rd_expect(A_STATUS, 32'h8, 1'b0, "low: level sets again");
        drive_pins(32'h9);
        idle(2);
        wr_expect(A_STATUS, 32'h8, 4'h1, 1'b0, "low: clear after level gone");
        rd_expect(A_STATUS, 32'h0, 1'b0, "low: cleared");
        wr_expect(A_LOW, 32'h0, 4'hF, 1'b0, "low disable");

        // ---- Partial W1C, mask, N=32 lane ----
        wr_expect(A_RISE, 32'h000100F0, 4'hF, 1'b0, "rise enable pins 4-7,16");
        rd_expect2(A_RISE, 32'h000000F0, 32'h000100F0, 1'b0, "rise enable readback");
        drive_pins(32'h000100F9);
        idle(2);
        rd_expect2(A_STATUS, 32'h000000F0, 32'h000100F0, 1'b0, "multi: status pending");
        chk((irq8 == 1'b0) && (irq32 == 1'b0), "mask: masked status, irq low");
        wr_expect(A_STATUS, 32'h0, 4'hF, 1'b0, "W1C: write zeros");
        rd_expect2(A_STATUS, 32'h000000F0, 32'h000100F0, 1'b0, "W1C: zeros keep status");
        wr_expect(A_EN, 32'h00010000, 4'hF, 1'b0, "mask: enable bit 16");
        chk(irq8 == 1'b0, "mask: N=8 bit 16 absent, irq low");
        chk(irq32 == 1'b1, "mask: N=32 bit 16 pending, irq high");
        wr_expect(A_EN, 32'h00000080, 4'hF, 1'b0, "mask: enable bit 7");
        chk((irq8 == 1'b1) && (irq32 == 1'b1), "mask: unmask pending bit 7");
        wr_expect(A_EN, 32'h0, 4'hF, 1'b0, "mask: disable all");
        chk((irq8 == 1'b0) && (irq32 == 1'b0), "mask: irq low again");
        wr_expect(A_STATUS, 32'h00000050, 4'h1, 1'b0, "W1C: clear bits 4,6");
        rd_expect2(A_STATUS, 32'h000000A0, 32'h000100A0, 1'b0, "W1C: only bits 4,6 cleared");
        wr_expect(A_STATUS, 32'hFFFFFFA0, 4'b1110, 1'b0, "W1C: byte 0 unstrobed");
        rd_expect2(A_STATUS, 32'h000000A0, 32'h000000A0, 1'b0, "W1C: unstrobed byte kept");
        wr_expect(A_STATUS, 32'h000000A0, 4'b0001, 1'b0, "W1C: clear bits 5,7");
        rd_expect(A_STATUS, 32'h0, 1'b0, "W1C: all cleared");

        // ---- Detection beats clear ----
        drive_pins(32'h0);
        idle(2);
        wr_expect(A_RISE, 32'h1, 4'hF, 1'b0, "rise enable bit 0 only");
        rd_expect(A_STATUS, 32'h0, 1'b0, "race: no status after falls");
        drive_pins(32'h1);
        idle(2);
        rd_expect(A_STATUS, 32'h1, 1'b0, "race: bit 0 pending");
        drive_pins(32'h0);
        idle(2);
        rd_expect(A_STATUS, 32'h1, 1'b0, "race: bit 0 still pending");
        apb_write_pin(A_STATUS, 32'h1, 4'h1, 32'h1);
        rd_expect(A_STATUS, 32'h1, 1'b0, "race: detection beats clear");
        wr_expect(A_STATUS, 32'h1, 4'h1, 1'b0, "race: clear again");
        rd_expect(A_STATUS, 32'h0, 1'b0, "race: cleared");
        wr_expect(A_RISE, 32'h0, 4'hF, 1'b0, "rise disable");

        // ---- Reset again ----
        wr_expect(A_DATA_OUT, 32'hFFFFFFFF, 4'hF, 1'b0, "pre-reset DATA_OUT");
        wr_expect(A_DIR,      32'hFFFFFFFF, 4'hF, 1'b0, "pre-reset DIR");
        wr_expect(A_EN,       32'h1, 4'hF, 1'b0, "pre-reset INTR_ENABLE");
        wr_expect(A_HIGH,     32'h1, 4'hF, 1'b0, "pre-reset INTR_HIGH");
        drive_pins(32'h1);
        idle(2);
        chk((irq8 == 1'b1) && (irq32 == 1'b1), "pre-reset: irq high");
        chk((gpio_out8 == 8'hFF) && (gpio_out32 == 32'hFFFFFFFF), "pre-reset: gpio_out high");
        chk((gpio_oe8 == 8'hFF) && (gpio_oe32 == 32'hFFFFFFFF), "pre-reset: gpio_oe high");
        @(negedge pclk);
        presetn = 1'b0;
        gin = 32'h0;
        @(posedge pclk); #1;
        chk((gpio_out8 == 8'h00) && (gpio_oe8 == 8'h00) && (irq8 == 1'b0), "reset2: N=8 outputs low");
        chk((gpio_out32 == 32'h0) && (gpio_oe32 == 32'h0) && (irq32 == 1'b0), "reset2: N=32 outputs low");
        @(posedge pclk);
        @(negedge pclk);
        presetn = 1'b1;
        check_all_zero;

        // ---- Verdict ----
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
